mapper.select:
SELECT a.id AS accountRowId, a.account_id AS accountCode, a.name AS accountName, UPPER(cur.code) AS currencyCode, COALESCE(SUM(CASE WHEN t.transaction_type = 'WIN' THEN t.amount ELSE 0 END), 0) AS winAmount, COALESCE(SUM(CASE WHEN t.transaction_type = 'LOSE' THEN t.amount ELSE 0 END), 0) AS loseAmount FROM account a INNER JOIN account_tenant_access ata ON ata.account_id = a.id AND ata.tenant_id = #{tenantId} INNER JOIN account_currency ac ON ac.account_id = a.id AND ac.tenant_id = #{tenantId} INNER JOIN currency cur ON cur.id = ac.currency_id AND cur.tenant_id = #{tenantId} LEFT JOIN transactions t ON t.account_id = a.id AND t.tenant_id = #{tenantId} AND t.currency_id = ac.currency_id AND t.bank_process_posted_id IS NULL AND t.transaction_type IN ('WIN', 'LOSE') AND t.transaction_date >= #{dateFrom} AND t.transaction_date <= #{dateTo}
AND a.id = #{accountId}
AND UPPER(cur.code) IN
UPPER(#{code})
GROUP BY a.id, a.account_id, a.name, cur.id, cur.code ORDER BY a.account_id ASC, cur.code ASC

SELECT p.id AS processRowId, p.code AS processCode, (SELECT GROUP_CONCAT(DISTINCT pd.name ORDER BY pd.name SEPARATOR ', ') FROM process_description_link pdl INNER JOIN process_description pd ON pd.id = pdl.description_id WHERE pdl.process_id = p.id) AS description, COALESCE(SUM(CASE WHEN t.transaction_type = 'WIN' THEN t.amount ELSE 0 END), 0) AS winAmount, COALESCE(SUM(CASE WHEN t.transaction_type = 'LOSE' THEN t.amount ELSE 0 END), 0) AS loseAmount FROM process p LEFT JOIN data_captures dc ON dc.process_id = p.id AND dc.tenant_id = p.tenant_id AND dc.capture_date >= #{dateFrom} AND dc.capture_date <= #{dateTo} LEFT JOIN data_capture_line dl ON dl.capture_id = dc.id AND dl.tenant_id = p.tenant_id LEFT JOIN transactions t ON t.id = dl.transaction_id AND t.tenant_id = p.tenant_id AND t.bank_process_posted_id IS NULL AND t.transaction_type IN ('WIN', 'LOSE')
AND p.tenant_id = #{tenantId} AND p.category = #{category}
AND p.id = #{processId}
GROUP BY p.id, p.code ORDER BY p.code ASC
